// «CI турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

const greenSteps = [
  { name: "checkout", run: () => true },
  { name: "install", run: () => true },
  { name: "test", run: () => true },
  { name: "build", run: () => true },
];

const redSteps = [
  { name: "checkout", run: () => true },
  { name: "install", run: () => true },
  { name: "test", run: () => false },
  { name: "build", run: () => true },
];

window.GREEN = null;
window.REDFAIL = null;

try {
  window.GREEN = runPipeline(greenSteps);
  window.REDFAIL = runPipeline(redSteps);
  panel(window.GREEN && window.GREEN.ok ? "ok" : "bad", "green", "Push #1 — бүх алхам ногоон", [JSON.stringify(window.GREEN, null, 2)]);
  panel(window.REDFAIL && !window.REDFAIL.ok ? "ok" : "bad", "red", "Push #2 — тест унана", [JSON.stringify(window.REDFAIL, null, 2)]);
} catch (problem) {
  panel("bad", "error", "Pipeline алдаа", [problem.message]);
}

document.body.dataset.ready = "1";

