// CI pipeline — push бүрд алхмуудыг ДАРААЛЛААР ажиллуулна.

function runPipeline(steps) {
  const results = [];
  let failed = false;

  for (const step of steps) {
    if (failed) {
      results.push({ name: step.name, status: "skipped" });
      continue;
    }
    const ok = step.run();
    results.push({ name: step.name, status: ok ? "passed" : "failed" });
    if (!ok) failed = true;
  }

  return { ok: !failed, results };
}
